export const CHANNELS={payhere:'페이히어',otter:'오터',naver:'네이버',baemin:'배민',coupang:'쿠팡이츠'};
export const isTransition=d=>d>='2026-01-01'&&d<='2026-08-31';
export function sourceProducts(pos,a){const direct=a?.direct,dates=new Set((direct?.daily||[]).map(r=>r.date));return pos.map(r=>({...r,channel:'payhere'})).filter(r=>!(dates.has(r.date)&&r.category==='배달앱')).concat((a?.products||[]).filter(r=>!(dates.has(r.date)&&r.channel==='otter')),direct?.products||[])}
export function renderDirect(a,{won,esc,nf}){if(!a)return '';const months=[...new Set(a.daily.map(r=>r.date.slice(0,7)))].sort().map(month=>{const rows=a.daily.filter(r=>r.date.startsWith(month));return {month,sales:rows.reduce((s,r)=>s+r.sales,0),pos:rows.reduce((s,r)=>s+r.payhereStore,0),delivery:rows.reduce((s,r)=>s+r.baemin+r.coupang,0),naver:rows.reduce((s,r)=>s+r.naver,0)}});return `<section class="direct-review"><h3>1~8월 배달 직접 원본 반영</h3><p>POS의 배달앱 항목을 제외하고 배민·쿠팡이츠 커피·젤라또 원본으로 대체했습니다. 오터는 이 기간에 중복 합산하지 않습니다.</p><div class="table-wrap"><table><thead><tr><th>월</th><th class="num">POS 매장</th><th class="num">배민·쿠팡이츠</th><th class="num">네이버</th><th class="num">매장 총매출</th></tr></thead><tbody>${months.map(r=>`<tr><td>${r.month}</td><td class="num">${won(r.pos)}</td><td class="num">${won(r.delivery)}</td><td class="num">${won(r.naver)}</td><td class="num"><b>${won(r.sales)}</b></td></tr>`).join('')}</tbody></table></div><p class="sub">${esc(a.policy)}</p><details><summary>플랫폼·매장별 대조 내역</summary><div class="table-wrap"><table><thead><tr><th>월</th><th>플랫폼·매장</th><th class="num">확인 순매출</th><th>반영 기준</th></tr></thead><tbody>${a.stores.map(r=>`<tr><td>${r.month}</td><td>${CHANNELS[r.channel]} · ${esc(r.store)}</td><td class="num">${won(r.sales)}</td><td>${esc(r.basis)}</td></tr>`).join('')}</tbody></table></div></details><a href="direct-delivery-review.csv" download>일별 대조표 CSV ↓</a> · <a href="excluded-pos-delivery.csv" download>제외한 POS 배달앱 내역 ↓</a></section>`}
export function renderChannelAudit(a,ui,expanded=false){
 if(!a)return '';const {won,esc}=ui;
 return `<details class="card channel-audit" ${expanded?'open':''}><summary><span class="badge">원본 대조</span> 2026년 1월부터 매출 반영 내역 <span class="positive">일별 합계 반영 완료</span></summary><div class="audit-body"><p>1월 1일~${a.asOf}까지의 매장 총매출을 확인한 채널 원본으로 집계했습니다. 1~8월은 배달 직접 원본, 9~10월은 오터 순매출을 사용합니다.</p>${renderDirect(a.direct,ui)}<div class="table-wrap"><table><thead><tr><th>월</th><th class="num">POS 원본</th><th class="num">제외한 POS 배달앱</th><th class="num">적용 배달 순매출</th><th class="num">네이버</th><th class="num">합산 총매출</th><th>반영 기준</th></tr></thead><tbody>${a.months.map(m=>`<tr><td>${m.month}</td><td class="num">${won(m.payhere)}</td><td class="num">${won(m.excludedPosDelivery||0)}</td><td class="num">${won(m.appliedDelivery)}</td><td class="num">${won(m.naver)}</td><td class="num"><b>${won(m.reconciledTotal)}</b></td><td>${esc(m.status)}</td></tr>`).join('')}</tbody></table></div><div class="note"><b>집계 범위와 남은 상세 자료</b><br>배민 가맹점 할인 누락 6건·6,000원과 확인한 부분환불을 반영했습니다. 전체 취소는 완료 매출에서 다시 차감하지 않습니다.<br>상품명이 없는 배달 금액은 ‘상품 상세 미확인’으로 보존합니다. 매출 합계 확보와 상품·옵션 상세 확보는 구분합니다.<br>2025년은 POS 365일 원본을 확보했습니다. 별도 배달·네이버 전체 원본은 없어 전년 대비는 동일 POS 원본끼리 비교합니다.</div><p class="sub">옵션은 상품액에 포함되어 별도 매출로 더하지 않습니다. 주간 POS 옵션은 10/12~18, 10/19~25 원본을 연결했으며 다른 기간으로 안분하지 않습니다. ${a.asOf}까지 최종 POS·오터·네이버 조회를 반영했습니다. 시간대별 POS 자료는 별도 날짜별 원본이 필요합니다.</p><a class="btn small" href="channel-monthly-audit.csv" download>↓ 월별 대조표 CSV</a></div></details>`;
}
export function channelNote(a){return a?.direct?a.direct.policy+' 9~10월은 POS + 오터 + 네이버 확인 원본 순매출을 합산합니다.':a?.policy||'채널 원본 반영 범위를 확인해 주세요.'}
